<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Personal Expense Tracker</title>
  <style>
    :root {
      color-scheme: light;
      font-family: Arial, sans-serif;
      background: #f4f6f8;
      color: #20252b;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      padding: 24px;
    }

    main {
      max-width: 850px;
      margin: 0 auto;
    }

    h1, h2 { margin-top: 0; }

    section {
      background: #fff;
      border: 1px solid #dce1e6;
      border-radius: 8px;
      padding: 20px;
      margin-bottom: 18px;
    }

    form, .filters {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 14px;
      align-items: end;
    }

    label {
      display: flex;
      flex-direction: column;
      gap: 6px;
      font-weight: 600;
      font-size: 0.9rem;
    }

    input, select, button {
      font: inherit;
      min-height: 38px;
      border: 1px solid #b9c2cc;
      border-radius: 5px;
      padding: 7px 9px;
    }

    button {
      cursor: pointer;
      background: #1769aa;
      border-color: #1769aa;
      color: white;
      font-weight: 600;
    }

    button:hover { background: #125487; }

    .error {
      min-height: 20px;
      margin: 12px 0 0;
      color: #b42318;
      font-weight: 600;
    }

    .summary-total {
      font-size: 1.25rem;
      margin-bottom: 16px;
    }

    .category-summary {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
      gap: 10px;
    }

    .cat-total {
      background: #f0f4f7;
      border-radius: 5px;
      padding: 10px;
    }

    .expense-list {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .expense {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr auto;
      gap: 12px;
      align-items: center;
      border: 1px solid #e0e5e9;
      border-radius: 5px;
      padding: 12px;
    }

    .expense small {
      display: block;
      color: #68737d;
      margin-top: 3px;
    }

    .expense .exp-del {
      background: #b42318;
      border-color: #b42318;
      min-height: 32px;
    }

    .expense .exp-del:hover { background: #8f1c14; }

    .empty {
      color: #68737d;
      text-align: center;
      padding: 14px;
    }

    @media (max-width: 600px) {
      .expense {
        grid-template-columns: 1fr 1fr;
      }

      .expense .exp-del {
        grid-column: 2;
        grid-row: 1 / span 2;
      }
    }
  </style>
</head>
<body>
  <main>
    <h1>Personal Expense Tracker</h1>

    <section>
      <h2>Add Expense</h2>
      <form id="expense-form">
        <label>
          Amount
          <input id="amount" type="number" min="0" step="0.01" inputmode="decimal">
        </label>

        <label>
          Category
          <select id="category">
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </label>

        <label>
          Date
          <input id="date" type="date">
        </label>

        <label>
          Note
          <input id="note" type="text" maxlength="200" placeholder="Optional">
        </label>

        <button id="add-expense" type="submit">Add Expense</button>
      </form>
      <p id="form-error" class="error" role="alert"></p>
    </section>

    <section>
      <h2>Filters</h2>
      <div class="filters">
        <label>
          Category
          <select id="filter-category">
            <option value="all">All categories</option>
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>
        </label>

        <label>
          From
          <input id="filter-from" type="date">
        </label>

        <label>
          To
          <input id="filter-to" type="date">
        </label>
      </div>
    </section>

    <section>
      <h2>Summary</h2>
      <div class="summary-total">Visible total: <strong id="total">0.00</strong></div>
      <div id="category-summary" class="category-summary"></div>
    </section>

    <section>
      <h2>Expenses</h2>
      <div id="expense-list" class="expense-list"></div>
    </section>
  </main>

  <script>
    (() => {
      const categories = ["groceries", "transport", "bills", "fun"];
      const storageKey = "personal-expenses";
      let expenses = [];

      try {
        const saved = JSON.parse(localStorage.getItem(storageKey) || "[]");
        expenses = Array.isArray(saved) ? saved : [];
      } catch {
        expenses = [];
      }

      const form = document.getElementById("expense-form");
      const amountInput = document.getElementById("amount");
      const categoryInput = document.getElementById("category");
      const dateInput = document.getElementById("date");
      const noteInput = document.getElementById("note");
      const error = document.getElementById("form-error");
      const list = document.getElementById("expense-list");
      const total = document.getElementById("total");
      const categoryFilter = document.getElementById("filter-category");
      const fromFilter = document.getElementById("filter-from");
      const toFilter = document.getElementById("filter-to");
      const categorySummary = document.getElementById("category-summary");

      function save() {
        localStorage.setItem(storageKey, JSON.stringify(expenses));
      }

      function visibleExpenses() {
        const selectedCategory = categoryFilter.value;
        const from = fromFilter.value;
        const to = toFilter.value;

        return expenses.filter(expense => {
          const categoryMatches =
            selectedCategory === "all" || expense.category === selectedCategory;
          const fromMatches = !from || expense.date >= from;
          const toMatches = !to || expense.date <= to;
          return categoryMatches && fromMatches && toMatches;
        });
      }

      function renderSummary(visible) {
        const sum = visible.reduce((value, expense) => value + expense.amount, 0);
        total.textContent = sum.toFixed(2);

        categorySummary.innerHTML = "";
        categories.forEach(category => {
          const categorySum = visible
            .filter(expense => expense.category === category)
            .reduce((value, expense) => value + expense.amount, 0);

          const item = document.createElement("div");
          item.className = "cat-total";
          item.dataset.cat = category;
          item.textContent = category + ": " + categorySum.toFixed(2);
          categorySummary.appendChild(item);
        });
      }

      function render() {
        const visible = visibleExpenses();
        const visibleIds = new Set(visible.map(expense => expense.id));
        const ordered = [...expenses].sort((a, b) => {
          if (a.date !== b.date) return b.date.localeCompare(a.date);
          return b.createdAt - a.createdAt;
        });

        list.innerHTML = "";

        ordered.forEach(expense => {
          const row = document.createElement("div");
          row.className = "expense";
          row.dataset.id = expense.id;
          row.hidden = !visibleIds.has(expense.id);

          const amount = document.createElement("div");
          amount.textContent = expense.amount.toFixed(2);

          const category = document.createElement("div");
          category.textContent = expense.category;

          const date = document.createElement("div");
          date.textContent = expense.date;
          if (expense.note) {
            const note = document.createElement("small");
            note.textContent = expense.note;
            date.appendChild(note);
          }

          const deleteButton = document.createElement("button");
          deleteButton.type = "button";
          deleteButton.className = "exp-del";
          deleteButton.textContent = "Delete";
          deleteButton.addEventListener("click", () => {
            expenses = expenses.filter(item => item.id !== expense.id);
            save();
            render();
          });

          row.append(amount, category, date, deleteButton);
          list.appendChild(row);
        });

        if (ordered.length === 0) {
          const empty = document.createElement("div");
          empty.className = "empty";
          empty.textContent = "No expenses recorded.";
          list.appendChild(empty);
        } else if (visible.length === 0) {
          const empty = document.createElement("div");
          empty.className = "empty";
          empty.textContent = "No expenses match the selected filters.";
          list.appendChild(empty);
        }

        renderSummary(visible);
      }

      form.addEventListener("submit", event => {
        event.preventDefault();
        const amount = Number(amountInput.value);
        const date = dateInput.value;

        if (!Number.isFinite(amount) || amount <= 0 || !date) {
          error.textContent = "Enter a positive amount and a date.";
          return;
        }

        expenses.push({
          id: String(Date.now()) + Math.random().toString(16).slice(2),
          amount,
          category: categoryInput.value,
          date,
          note: noteInput.value.trim(),
          createdAt: Date.now()
        });

        save();
        error.textContent = "";
        amountInput.value = "";
        render();
      });

      [categoryFilter, fromFilter, toFilter].forEach(control => {
        control.addEventListener("change", render);
      });

      render();
    })();
  </script>
</body>
</html>
